function validate([nums]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => v < -100 || v > 100)) return 'Each value is between -100 and 100.';
  // The problem promises a 32-bit answer; every F(k) is checked with the one-step update.
  let total = 0, value = 0;
  for (let i = 0; i < n; i++) { total += nums[i]; value += i * nums[i]; }
  let best = value;
  for (let k = 1; k < n; k++) { value += total - n * nums[n - k]; best = Math.max(best, value); }
  if (best > 2147483647 || best < -2147483648) return 'The answer must fit in a 32-bit signed integer.';
  return null;
}

