function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const span = large || rand() < 0.5 ? 100 : 3;
  return [Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span)];
